// Genuary #20: Generative Architecture
// Based on a piece by Olafur Eliasson but then I messed up and found it pwetty
// https://olafureliasson.net/


#define rot(a) mat2(cos(a), sin(a), -sin(a), cos(a))
#define noi(u) textureLod(iChannel0, u, 0.).x
#define crep(p, c, l) p-=c*clamp(round(p/c), -l, l)

struct obj{
    float d;
    int mat;
    vec3 c;
};

obj minobj (obj a, obj b)
{
    if (a.d < b.d) return a;
    else return b;
}

float box(vec3 b, vec3 pos, vec3 p)
{
    vec3 q = abs(p - pos) - b;
  	return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);
}

float emptyBox(vec3 b, vec3 pos, vec3 p, float inner)
{
    return max(box(b, pos, p), -box(b * inner, pos, p));
}

float grid (vec3 p)
{
    p.z -= 1.6;
    float per = .25;
    vec2 id = round(p.xy/per);
    float n = noi((id+11.)*0.017);
    p.xy = crep(p.xy, per, vec2(8., 3.));

    float r = mix(0., per*.6, clamp(n-.2, 0., 1.));
    float d = length(p)-r;

    return d;
}


float g1 = 0.;
obj SDF (vec3 p, bool glow)
{
    float room = emptyBox(vec3(2.5, 1.5, 2), vec3(0), p, 0.9);
    float window = box(vec3(3, 0.8, 1), vec3(1, 0, 0), p);
    obj allRoom = obj(max(room, -window), 0, vec3(1.));

    float d = grid(p);
    obj allGrid = obj(grid(p), 1, vec3(1.));

    if(glow) g1 += 0.01/(0.01+d*d);

    return minobj(allRoom, allGrid);
}

vec3 gn (vec3 p, float e)
{
    vec2 eps = vec2(e, 0.);
    return normalize(vec3(SDF(p, false).d-vec3(SDF(p-eps.xyy, false).d,SDF(p-eps.yxy, false).d,SDF(p-eps.yyx, false).d)));
}

void shadow (inout float s, vec3 ro, vec3 rd)
{
    float t;
    vec3 p;
    obj O;
    for (float i=0.; i<100.; i++)
    {
        p = ro+rd*t;
        O = SDF(p, false);
        if (O.d<0.001)
        {
            s = 0.25;
        }
        if (t > 10.) break;
        t += O.d;
    }
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (2.*fragCoord-iResolution.xy)/iResolution.y;

    vec3 ro = vec3(0.001,-0.01,0.3), rd =normalize(vec3(uv, 1.)), p=ro,
    col=vec3(0.), l=normalize(vec3(7.5,.5,-2.));
    l.xz *= rot(sin(iTime)*.5+.5);

    obj O;
    for (float i=0.; i<100.; i++)
    {
        O = SDF(p, true);
        if (O.d<0.001)
        {
            vec3 n = gn(p, 0.001);
            if (O.mat == 0)
            {
                rd = reflect(rd, n);
                p += 0.1*n;
            }
            if (O.mat == 1)
            {
                rd = refract(rd, n, 1.25);
                p += n*0.1;
                p *= sign(p);                
            }
        }
        p += O.d*rd;
    }

    float s = 1.;
    vec3 n = gn(p, 0.001);
    if (O.mat == 0)
    {
        col = texture(iChannel2, p).xyz;
    }
    if (O.mat == 1)
    {
        col = texture(iChannel1, p).xyz;
    }

    shadow(s, p+n*0.001, l);
    col *= s;

    col += g1*0.012;

    fragColor = vec4(sqrt(col),1.0);
}
